1	import { precompile } from '../../components/effects/shaderWarmup.ts';
2	import React, { useEffect, useMemo, useRef } from 'react';
3	import { useFrame } from '@react-three/fiber';
4	import { CuboidCollider, RigidBody } from '@react-three/rapier';
5	import * as THREE from 'three';
6	import { voxelSystem } from '../../utils/efficientVoxelSystem.ts';
7	import { VOXEL_SCALE } from '../../utils/cubeGravityConstants.ts';
8	import { createLiveAgentSurfaceTerrain } from '../../utils/agentSurfaceNavigationRuntime.ts';
9	import { heroTreeHandle } from './HeroAppleTree.tsx';
10	import {
11	  CG_APPARATUS_SOLIDS,
12	  PLAYER_BODY_HEIGHT,
13	  TRACE_GLYPH_THICKNESS,
14	  commonGuideGlyphs,
15	  commonTestedGlyphs,
16	  firstUnsupportedSegment,
17	  traceGlyphs,
18	  type CommonGroundAabb,
19	  type CommonGroundFooting,
20	  type TraceGlyph
21	} from '../commonGroundRoute.ts';
22	import {
23	  CG_ROUTE_COMMON,
24	  MAX_TRACE_POINTS,
25	  commonGroundCommonDisplay,
26	  readCommonGroundLive,
27	  type CommonGroundDisplayKind,
28	  type CommonGroundPoint,
29	  type TraceSlot
30	} from '../commonGroundState.ts';
31	import { registerCommonGroundWorld } from '../commonGroundDirector.ts';
32	import { restoreCommonGroundForWorld } from '../../game/systems/persistence.ts';
33	
34	// --- The survey apparatus and the drawn trace ----------------------------------------
35	//
36	// The apparatus is four boxes and the trace is up to 512 pooled glyphs, and both
37	// are single instanced meshes sharing one material each. That is the INTENDED
38	// shape against the accepted +8 draw / +6 material / +6 program / +2 MiB budget;
39	// it is a design claim, not a measurement, and no render or resource budget is
40	// claimed as verified here — an independent capture owns that.
41	//
42	// SHAPE CARRIES STATE, NOT COLOUR. Every glyph comes out of the same prewarmed
43	// material, so a proposed sample, a tested sample, a stopped end and the planned
44	// common guide have to be told apart by their form alone — which is the only way
45	// they survive a muted, unlit, lowest-tier frame. The one unwalked line in the
46	// chapter is the common E-to-C guide, and it appears only after W-7744 has
47	// physically reached H. The S-to-E survey is never previewed.
48	//
49	// NO NEW LIGHT. Light cardinality is fixed at the shipped count; the instrument
50	// reads by its own silhouette against the ground, which is also why it must be
51	// legible at POTATO with no effect at all.
52	//
53	// Everything is allocated and precompiled at MOUNT, before any critical verb:
54	// the ±2 second window around the offer, the start, the span offer, the hold,
55	// the revision and the completion must contain zero first-use of a program or a
56	// resource, and there are no frame-loop allocations below.
57	
58	/** The body's grounded clearance above its support surface, as qualified. */
59	const GROUND_CLEARANCE = 1.05;
60	/**
61	 * Pooled trace glyphs: two recorded routes × 128 samples × at most 2 glyphs.
62	 *
63	 * The signed grammar costs two instances per represented sample — one bar for a
64	 * proposed sample, a parallel pair for a tested one, and a two-piece open stop
65	 * that REPLACES a pair rather than adding to it — so 2 × 128 × 2 is exactly 512
66	 * and the ceiling is structural rather than a hope. The common guide and the
67	 * completed common display share the working route's half of that pool.
68	 */
69	const TRACE_GLYPH_POOL = 512;
70	
71	const APPARATUS_COLOR = '#8d9a95';
72	const APPARATUS_DARK = '#55605d';
73	/** The trace reads as her own line: the shipped ember, not a new accent. */
74	const TRACE_COLOR = '#ff5a3c';
75	
76	function cell(value: number): number {
77	  return Math.round(value / VOXEL_SCALE);
78	}
79	
80	/**
81	 * Live footing over the actual voxel world.
82	 *
83	 * The support column is the cell whose top face the body stands on
84	 * (`y - 1.05`), the cell above it must be empty, and neither may be water. The
85	 * body disc is sampled at its centre and at four lateral offsets, so a foot
86	 * half over a hole is not "supported" merely because its centre is.
87	 */
88	function createFooting(planetSize: number, terrainSeed: number, worldId: string): CommonGroundFooting {
89	  const terrain = createLiveAgentSurfaceTerrain(planetSize, terrainSeed, worldId);
90	  const supportedColumn = (x: number, y: number, z: number): boolean => {
91	    const cx = cell(x);
92	    const cz = cell(z);
93	    const cy = cell(y - GROUND_CLEARANCE);
94	    if (!terrain.isSolidVoxel(cx, cy, cz)) return false;
95	    if (terrain.isSolidVoxel(cx, cy + 1, cz)) return false;
96	    if (terrain.isWaterVoxel(cx, cy, cz) || terrain.isWaterVoxel(cx, cy + 1, cz)) return false;
97	    if (terrain.isHazardousVoxel?.(cx, cy, cz)) return false;
98	    return true;
99	  };
100	  return {
101	    // LIVE, NOT CAPTURED. `createLiveAgentSurfaceTerrain` builds its revision
102	    // string once, so copying it would pin the value at mount and every later
103	    // edit would look like no edit at all. The predicates below already read the
104	    // voxel system live; this makes the invalidation token agree with them.
105	    get revision(): string {
106	      return `${voxelSystem.getWorldId()}:${voxelSystem.getEditVersion()}`;
107	    },
108	    isSupported: (point: CommonGroundPoint) => supportedColumn(point.x, point.y, point.z)
109	      && supportedColumn(point.x + 0.5, point.y, point.z)
110	      && supportedColumn(point.x - 0.5, point.y, point.z)
111	      && supportedColumn(point.x, point.y, point.z + 0.5)
112	      && supportedColumn(point.x, point.y, point.z - 0.5)
113	  };
114	}
115	
116	/** The hero tree's EXISTING trunk collider, included in the route guard. */
117	function trunkSolid(): CommonGroundAabb | null {
118	  const position = heroTreeHandle.position;
119	  if (!position) return null;
120	  const height = Math.max(1, heroTreeHandle.height ?? 7.2);
121	  return {
122	    name: 'hero-tree-trunk',
123	    lo: { x: position.x - 0.55, y: position.y, z: position.z - 0.55 },
124	    hi: { x: position.x + 0.55, y: position.y + height, z: position.z + 0.55 }
125	  };
126	}
127	
128	const _matrix = new THREE.Matrix4();
129	const _position = new THREE.Vector3();
130	const _quaternion = new THREE.Quaternion();
131	const _scale = new THREE.Vector3();
132	const _euler = new THREE.Euler();
133	
134	/**
135	 * Per-slot allocation ceiling.
136	 *
137	 * Two recorded routes of at most 128 samples, at most two glyphs each, is
138	 * exactly the existing 512 pool. The accepted survey keeps its own half whenever
139	 * it exists, and the common display SHARES the working half rather than asking
140	 * for a third allocation: while an optional repeat is being drawn, the working
141	 * route owns that half and the common display yields it.
142	 */
143	const SLOT_GLYPH_ALLOCATION = MAX_TRACE_POINTS * 2;
144	
145	/**
146	 * What the pooled mesh is currently showing.
147	 *
148	 * Kept as mutable primitives rather than a rebuilt key string so a resting frame
149	 * does no work and allocates nothing: the layout is recomputed only when a
150	 * recorded sample, a tested prefix, a real hold, the common display state or the
151	 * live terrain revision has ACTUALLY changed.
152	 */
153	interface TraceDisplayCache {
154	  accepted: TraceSlot | null;
155	  acceptedSamples: number;
156	  acceptedTested: number;
157	  working: TraceSlot | null;
158	  workingSamples: number;
159	  workingTested: number;
160	  workingRevision: number;
161	  heldIndex: number;
162	  display: CommonGroundDisplayKind;
163	  terrain: string;
164	  active: boolean;
165	}
166	
167	function writeGlyphs(mesh: THREE.InstancedMesh, glyphs: readonly TraceGlyph[], from: number): number {
168	  let index = from;
169	  for (const glyph of glyphs) {
170	    if (index >= mesh.instanceMatrix.count) break;
171	    _position.set(glyph.x, glyph.y, glyph.z);
172	    _euler.set(0, -glyph.angle, 0);
173	    _quaternion.setFromEuler(_euler);
174	    _scale.set(glyph.lengthUnits, TRACE_GLYPH_THICKNESS, glyph.widthUnits);
175	    mesh.setMatrixAt(index, _matrix.compose(_position, _quaternion, _scale));
176	    index += 1;
177	  }
178	  return index;
179	}
180	
181	const CommonGroundWorld: React.FC<{
182	  planetSize: number;
183	  terrainSeed: number;
184	  worldId: string;
185	  /** True only while a ch13 beat owns the frame; the sandbox never mounts this. */
186	  active: boolean;
187	}> = ({ planetSize, terrainSeed, worldId, active }) => {
188	  const groupRef = useRef<THREE.Group>(null);
189	  const apparatusRef = useRef<THREE.InstancedMesh>(null);
190	  const traceRef = useRef<THREE.InstancedMesh>(null);
191	  // The SAME footing and solids the director's route queries use, so the guide's
192	  // grounding answer cannot disagree with the walk mask's.
193	  const footingRef = useRef<CommonGroundFooting | null>(null);
194	  const solidsRef = useRef<readonly CommonGroundAabb[]>([]);
195	  const cacheRef = useRef<TraceDisplayCache>({
196	    accepted: null,
197	    acceptedSamples: -1,
198	    acceptedTested: -1,
199	    working: null,
200	    workingSamples: -1,
201	    workingTested: -1,
202	    workingRevision: -1,
203	    heldIndex: -2,
204	    display: 'none',
205	    terrain: '�',
206	    active: false
207	  });
208	
209	  const materials = useMemo(() => ({
210	    housing: new THREE.MeshStandardMaterial({ color: APPARATUS_COLOR, roughness: 0.8, metalness: 0.1 }),
211	    trace: new THREE.MeshStandardMaterial({
212	      color: TRACE_COLOR,
213	      roughness: 0.9,
214	      emissive: new THREE.Color(TRACE_COLOR),
215	      emissiveIntensity: 0.35
216	    })
217	  }), []);
218	  useEffect(() => () => {
219	    materials.housing.dispose();
220	    materials.trace.dispose();
221	  }, [materials]);
222	
223	  // The apparatus never moves, so its instance matrices are written once, at
224	  // mount, and the buffer is then static for the whole chapter.
225	  useEffect(() => {
226	    const mesh = apparatusRef.current;
227	    if (!mesh) return;
228	    CG_APPARATUS_SOLIDS.forEach((box, index) => {
229	      _position.set((box.lo.x + box.hi.x) / 2, (box.lo.y + box.hi.y) / 2, (box.lo.z + box.hi.z) / 2);
230	      _scale.set(box.hi.x - box.lo.x, box.hi.y - box.lo.y, box.hi.z - box.lo.z);
231	      _quaternion.identity();
232	      mesh.setMatrixAt(index, _matrix.compose(_position, _quaternion, _scale));
233	    });
234	    mesh.count = CG_APPARATUS_SOLIDS.length;
235	    mesh.instanceMatrix.needsUpdate = true;
236	    mesh.frustumCulled = false;
237	  }, []);
238	
239	  // PREWARM. Compile both programs and upload both buffers at mount, so the
240	  // first offered span cannot be the frame that compiles a shader.
241	  useEffect(() => {
242	    const root = groupRef.current;
243	    if (root) return precompile(root);
244	  }, []);
245	
246	  // This world's saved chapter state, staged for the director to validate. The
247	  // same reset-then-load shape every other per-world field uses.
248	  useEffect(() => {
249	    if (!worldId) return;
250	    restoreCommonGroundForWorld({ worldId, seed: terrainSeed });
251	  }, [terrainSeed, worldId]);
252	
253	  useEffect(() => {
254	    // READINESS GATES THE QUERIES. Binding before this world's voxels are the
255	    // resident ones would answer route questions about somebody else's ground.
256	    if (!active || !worldId) return;
257	    const footing = createFooting(planetSize, terrainSeed, worldId);
258	    const trunk = trunkSolid();
259	    const extraSolids = trunk ? [trunk] : [];
260	    footingRef.current = footing;
261	    solidsRef.current = extraSolids;
262	    const release = registerCommonGroundWorld({ worldId, footing, extraSolids });
263	    return () => {
264	      footingRef.current = null;
265	      solidsRef.current = [];
266	      release();
267	    };
268	  }, [active, planetSize, terrainSeed, worldId]);
269	
270	  // PREALLOCATE EVERY GLYPH BEFORE ANY VERB. The pool's whole matrix buffer is
271	  // written and uploaded once at mount, with the instances parked at zero scale,
272	  // so the frame that first offers, holds, reveals the guide or completes the
273	  // comparison only rewrites matrices that already exist. No instance attribute
274	  // is created, resized or first-used inside a critical window.
275	  useEffect(() => {
276	    const mesh = traceRef.current;
277	    if (!mesh) return;
278	    _position.set(0, 0, 0);
279	    _quaternion.identity();
280	    _scale.set(0, 0, 0);
281	    _matrix.compose(_position, _quaternion, _scale);
282	    for (let index = 0; index < TRACE_GLYPH_POOL; index += 1) mesh.setMatrixAt(index, _matrix);
283	    mesh.count = 0;
284	    mesh.instanceMatrix.needsUpdate = true;
285	    mesh.frustumCulled = false;
286	  }, []);
287	
288	  useFrame(() => {
289	    const mesh = traceRef.current;
290	    if (!mesh) return;
291	    const snapshot = active ? readCommonGroundLive(worldId) : null;
292	    const survey = snapshot?.survey ?? null;
293	    const accepted = survey?.accepted ?? null;
294	    const working = survey?.working ?? null;
295	    // THE HOLD BELONGS TO THE PROPOSAL BEING TESTED. An accepted route is a route
296	    // whose test finished; it has no stopped end to draw.
297	    const heldIndex = survey && survey.hold.reason !== null ? survey.hold.atIndex : -1;
298	    const display = snapshot ? commonGroundCommonDisplay(snapshot) : 'none';
299	    const ground = footingRef.current;
300	    const terrain = ground?.revision ?? '';
301	
302	    const cache = cacheRef.current;
303	    if (
304	      cache.active === active
305	      && cache.accepted === accepted
306	      && cache.acceptedSamples === (accepted?.samples.length ?? 0)
307	      && cache.acceptedTested === (accepted?.testedPrefixCount ?? 0)
308	      && cache.working === working
309	      && cache.workingSamples === (working?.samples.length ?? 0)
310	      && cache.workingTested === (working?.testedPrefixCount ?? 0)
311	      && cache.workingRevision === (working?.tailRevision ?? 0)
312	      && cache.heldIndex === heldIndex
313	      && cache.display === display
314	      && cache.terrain === terrain
315	    ) return;
316	    cache.active = active;
317	    cache.accepted = accepted;
318	    cache.acceptedSamples = accepted?.samples.length ?? 0;
319	    cache.acceptedTested = accepted?.testedPrefixCount ?? 0;
320	    cache.working = working;
321	    cache.workingSamples = working?.samples.length ?? 0;
322	    cache.workingTested = working?.testedPrefixCount ?? 0;
323	    cache.workingRevision = working?.tailRevision ?? 0;
324	    cache.heldIndex = heldIndex;
325	    cache.display = display;
326	    cache.terrain = terrain;
327	
328	    let count = 0;
329	    // THE ACCEPTED SURVEY SURVIVES A NEW PROPOSAL. It is earned evidence, and an
330	    // optional repeat draws alongside it rather than over it.
331	    if (accepted && accepted.samples.length > 0) {
332	      count = writeGlyphs(
333	        mesh,
334	        traceGlyphs(accepted.samples, { testedPrefixCount: accepted.testedPrefixCount }),
335	        count
336	      );
337	      count = Math.min(count, SLOT_GLYPH_ALLOCATION);
338	    }
339	    if (working && working.samples.length > 0) {
340	      // Capacity already stopped honestly in the slot itself; nothing is
341	      // decimated here either.
342	      count = writeGlyphs(
343	        mesh,
344	        traceGlyphs(working.samples, {
345	          testedPrefixCount: working.testedPrefixCount,
346	          heldIndex
347	        }),
348	        count
349	      );
350	    } else if (display !== 'none') {
351	      // The common display uses the RELEASED WORKING ALLOCATION. It is drawn only
352	      // while no proposal owns that half, which is exactly the lifecycle the lane
353	      // describes: the guide appears after the survey is accepted, and an
354	      // optional repeat takes the allocation back.
355	      if (display === 'planned-guide') {
356	        // PLANNED AND UNVERIFIED, AND GROUNDED. The line follows the existing
357	        // qualified polyline and stops where the live ground actually stops
358	        // carrying it; it never floats over an edit and never replans around one.
359	        const bad = ground
360	          ? firstUnsupportedSegment(CG_ROUTE_COMMON, ground, {
361	              extraSolids: solidsRef.current,
362	              bodyHeight: PLAYER_BODY_HEIGHT
363	            })
364	          : -1;
365	        const supportedThrough = bad < 0 ? CG_ROUTE_COMMON.length - 1 : bad - 1;
366	        count = writeGlyphs(mesh, commonGuideGlyphs(CG_ROUTE_COMMON, supportedThrough), count);
367	      } else {
368	        count = writeGlyphs(mesh, commonTestedGlyphs(CG_ROUTE_COMMON), count);
369	      }
370	    }
371	    mesh.count = Math.min(count, TRACE_GLYPH_POOL);
372	    mesh.instanceMatrix.needsUpdate = true;
373	    mesh.frustumCulled = false;
374	  });
375	
376	  return (
377	    <group ref={groupRef}>
378	      {/*
379	        REAL COLLIDERS, not just a walk-mask entry. The route guard stops the
380	        chapter from PLANNING through the housing; it cannot stop the player's
381	        live body walking through a thing they can see. The same literal AABBs
382	        are registered as fixed colliders, the way the hero tree's trunk already
383	        is: the instrument is real, and you cannot walk through the argument.
384	      */}
385	      {active && (
386	        <RigidBody type="fixed" colliders={false}>
387	          {CG_APPARATUS_SOLIDS.map(box => (
388	            <CuboidCollider
389	              key={box.name}
390	              args={[
391	                (box.hi.x - box.lo.x) / 2,
392	                (box.hi.y - box.lo.y) / 2,
393	                (box.hi.z - box.lo.z) / 2
394	              ]}
395	              position={[
396	                (box.lo.x + box.hi.x) / 2,
397	                (box.lo.y + box.hi.y) / 2,
398	                (box.lo.z + box.hi.z) / 2
399	              ]}
400	            />
401	          ))}
402	        </RigidBody>
403	      )}
404	      <instancedMesh
405	        ref={apparatusRef}
406	        args={[undefined, undefined, CG_APPARATUS_SOLIDS.length]}
407	        material={materials.housing}
408	        castShadow={false}
409	        receiveShadow={false}
410	      >
411	        <boxGeometry args={[1, 1, 1]} />
412	      </instancedMesh>
413	      <instancedMesh
414	        ref={traceRef}
415	        args={[undefined, undefined, TRACE_GLYPH_POOL]}
416	        material={materials.trace}
417	        castShadow={false}
418	        receiveShadow={false}
419	      >
420	        <boxGeometry args={[1, 1, 1]} />
421	      </instancedMesh>
422	    </group>
423	  );
424	};
425	
426	export default CommonGroundWorld;
427	export { APPARATUS_DARK, createFooting, trunkSolid, TRACE_GLYPH_POOL };

