function requestAnchorActivation(anchorId: string): void {
  if (activateSignedSceneAnchorById(anchorId)) {
    const at = runtime.pendingAnchors.indexOf(anchorId);
    if (at >= 0) runtime.pendingAnchors.splice(at, 1);
    return;
  }
