it('never defers the LIVE install acknowledgement across a pause', () => {
  // The rule this protects is unchanged: a refusal that survives the frame it
  // belonged to is a refusal, so no live install receipt can be held back and
  // then published when the coast clears. `anc.cg.cell-installed` is published
  // mid-beat, from the install boundary, and it goes through the ordinary
  // pending queue that a pause still empties on the spot.
  completeStory();
  standTidegardenHome();
  expect(tickCommonGroundEntry(0.016)).toBe(false);
  seedPriorBoundaryReceipts();
  // Publish the acknowledgement while the rail is deliberately elsewhere...
  resetSignedSceneAvRuntime('sandbox');
  expect(tickCommonGroundEntry(0.016)).toBe(true);
  expect(activatedAnchors()).not.toContain('anc.cg.cell-installed');
  // ...then pause before its retry can run.
  suspendCommonGroundPresentation('pause');
  enterSignedSceneAvBeat('ch13-home', 'quit');
  tickCommonGround(0.016);
  tickCommonGround(0.016);
  expect(activatedAnchors()).not.toContain('anc.cg.cell-installed');
