  // acknowledgement is gone rather than deferred.
  expect((getCommonGroundDiagnostic().anchors as string[])).toContain('anc.cg.cell-installed');
  expect(getCommonGroundProbeSnapshot().pendingAnchors).not.toContain('anc.cg.cell-installed');
});

