    })).toBe(true);
    enterCommonGroundBeat('ch13-home');
    standAt({ x: -20, y: 51.05, z: 40 });

    const harness = createRailHarness(0.05);
    harness.run(600, () => commonGroundSnapshot().home.returnChosen);

    expect(harness.acts.map(act => act.id)).toEqual([
